public int[][] merge(int[][] intervals) {
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
    List<int[]> merged = new ArrayList<>();
    for (int[] interval : intervals) {
        if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < interval[0]) {
            merged.add(interval);
        } else {
            merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], interval[1]);
        }
    }
    return merged.toArray(new int[merged.size()][]);
}

public int minMeetingRooms(int[][] intervals) {
    if (intervals == null || intervals.length == 0) return 0;
    Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();
    minHeap.offer(intervals[0][1]);
    for (int i = 1; i < intervals.length; i++) {
        if (intervals[i][0] >= minHeap.peek()) {
            minHeap.poll(); // Room is freed up
        }
        minHeap.offer(intervals[i][1]);
    }
    return minHeap.size();
}

public int[][] intervalIntersection(int[][] firstList, int[][] secondList) {
    List<int[]> result = new ArrayList<>();
    int i = 0, j = 0;
    while (i < firstList.length && j < secondList.length) {
        int start = Math.max(firstList[i][0], secondList[j][0]);
        int end = Math.min(firstList[i][1], secondList[j][1]);
        if (start <= end) result.add(new int[]{start, end});
        if (firstList[i][1] < secondList[j][1]) i++;
        else j++;
    }
    return result.toArray(new int[result.size()][]);
}

public int findMinArrowShots(int[][] points) {
    if (points.length == 0) return 0;
    Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));
    int arrows = 1;
    int arrowPos = points[0][1];
    for (int i = 1; i < points.length; i++) {
        if (points[i][0] > arrowPos) {
            arrows++;
            arrowPos = points[i][1];
        }
    }
    return arrows;
}

// My Calendar I using TreeMap
class MyCalendar {
    private TreeMap<Integer, Integer> calendar;
    public MyCalendar() { calendar = new TreeMap<>(); }
    public boolean book(int start, int end) {
        Integer prev = calendar.floorKey(start);
        Integer next = calendar.ceilingKey(start);
        if ((prev == null || calendar.get(prev) <= start) && (next == null || end <= next)) {
            calendar.put(start, end);
            return true;
        }
        return false;
    }
}

public boolean carPooling(int[][] trips, int capacity) {
    Map<Integer, Integer> timeline = new TreeMap<>();
    for (int[] trip : trips) {
        int passengers = trip[0];
        timeline.put(trip[1], timeline.getOrDefault(trip[1], 0) + passengers);
        timeline.put(trip[2], timeline.getOrDefault(trip[2], 0) - passengers);
    }
    int currCapacity = 0;
    for (int delta : timeline.values()) {
        currCapacity += delta;
        if (currCapacity > capacity) return false;
    }
    return true;
}

// Concept for The Skyline Problem
public List<List<Integer>> getSkyline(int[][] buildings) {
    List<int[]> heights = new ArrayList<>();
    for (int[] b : buildings) {
        heights.add(new int[]{b[0], -b[2]}); // start, negative height
        heights.add(new int[]{b[1], b[2]});  // end, positive height
    }
    Collections.sort(heights, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
    TreeMap<Integer, Integer> heightMap = new TreeMap<>(Collections.reverseOrder());
    heightMap.put(0, 1);
    int prevMax = 0;
    List<List<Integer>> sky = new ArrayList<>();
    for (int[] h : heights) {
        if (h[1] < 0) heightMap.merge(-h[1], 1, Integer::sum);
        else heightMap.merge(h[1], -1, Integer::sum);
        if (heightMap.get(h[1]) == 0) heightMap.remove(h[1]);
        int currMax = heightMap.firstKey();
        if (currMax != prevMax) {
            sky.add(Arrays.asList(h[0], currMax));
            prevMax = currMax;
        }
    }
    return sky;
}
